	}

	info := CodecInfo{Video: VideoCodecH264, Audio: AudioCodecAAC, Container: ContainerMKV}
	exporter.SetCodecInfo(info)

	exporter.mu.Lock()
	defer exporter.mu.Unlock()
	if !exporter.codecDetected {
